import "../../_virtual/_rolldown/runtime.js";
import { useCallbackRef } from "../../hooks/useCallbackRef.js";
import { createContext, useContext, useMemo } from "react";
import { shallowEqual } from "fast-equals";
import { nonNullable } from "@likec4/core";
import { useSelector } from "@xstate/react";
//#region src/overlays/relationship-details/hooks.ts
var RelationshipDetailsActorContext = createContext(null);
function useRelationshipDetailsActor() {
	return nonNullable(useContext(RelationshipDetailsActorContext), "No RelationshipDetailsActorContext");
}
function useRelationshipDetailsState(selector, compare = shallowEqual) {
	const select = useCallbackRef(selector);
	return useSelector(useRelationshipDetailsActor(), select, compare);
}
function useRelationshipDetails() {
	const actor = useRelationshipDetailsActor();
	return useMemo(() => ({
		actor,
		get rootElementId() {
			return `relationship-details-${actor.sessionId.replaceAll(":", "_")}`;
		},
		getState: () => actor.getSnapshot().context,
		send: actor.send,
		navigateTo: (...params) => {
			if (params.length === 1) actor.send({
				type: "navigate.to",
				params: { edgeId: params[0] }
			});
			else actor.send({
				type: "navigate.to",
				params: {
					source: params[0],
					target: params[1]
				}
			});
		},
		fitDiagram: () => {
			actor.send({ type: "fitDiagram" });
		},
		close: () => {
			if (actor._parent) actor._parent?.send({
				type: "close",
				actorId: actor.id
			});
			else actor.send({ type: "close" });
		}
	}), [actor]);
}
//#endregion
export { RelationshipDetailsActorContext, useRelationshipDetails, useRelationshipDetailsActor, useRelationshipDetailsState };
