import "../_virtual/_rolldown/runtime.js";
import { useCallbackRef } from "./useCallbackRef.js";
import { useDiagramActorRef } from "./safeContext.js";
import { deriveToggledFeatures } from "../likec4diagram/state/machine.setup.js";
import { shallowEqual } from "fast-equals";
import { nonNullable } from "@likec4/core";
import { useSelector } from "@xstate/react";
//#region src/hooks/useDiagramCompareLayout.ts
var selectCompareLayoutState = ({ context }) => {
	const drifts = context.view.drifts ?? null;
	if (!context.features.enableCompareWithLatest || !drifts || drifts.length === 0) return {
		hasEditor: false,
		isEnabled: false,
		isEditable: false,
		isActive: false,
		drifts: null,
		canApplyLatest: false,
		layout: context.view._layout ?? "auto"
	};
	const { enableCompareWithLatest, enableReadOnly } = deriveToggledFeatures(context);
	return {
		hasEditor: context.features.enableEditor,
		isEnabled: true,
		isEditable: !enableReadOnly,
		isActive: enableCompareWithLatest === true,
		drifts,
		canApplyLatest: !drifts.includes("type-changed"),
		layout: context.view._layout ?? "auto"
	};
};
function useDiagramCompareLayout() {
	const actorRef = useDiagramActorRef();
	const state = useSelector(actorRef, selectCompareLayoutState, shallowEqual);
	const switchLayout = useCallbackRef((layoutType) => {
		if (!state.isEnabled) {
			console.warn("Compare with latest feature is not enabled");
			return;
		}
		actorRef.send({
			type: "emit.onLayoutTypeChange",
			layoutType
		});
	});
	return [state, {
		toggleCompare: useCallbackRef((force) => {
			if (!state.isEnabled) {
				console.warn("Compare with latest feature is not enabled");
				return;
			}
			const nextIsActive = force ? force === "on" : !state.isActive;
			if (state.isActive && !nextIsActive && state.layout === "auto") switchLayout("manual");
			actorRef.send({
				type: "toggle.feature",
				feature: "CompareWithLatest",
				forceValue: nextIsActive
			});
		}),
		switchLayout,
		resetManualLayout: useCallbackRef(() => {
			if (!state.isEnabled) {
				console.warn("Compare with latest feature is not enabled");
				return;
			}
			actorRef.send({ type: "layout.resetManualLayout" });
		}),
		applyLatestToManual: useCallbackRef(() => {
			if (!state.isEnabled) {
				console.warn("Compare with latest feature is not enabled");
				return;
			}
			nonNullable(actorRef.system?.get("editor"), "editor actor not found").send({ type: "applyLatestToManual" });
			if (state.isActive) actorRef.send({
				type: "toggle.feature",
				feature: "CompareWithLatest",
				forceValue: false
			});
		})
	}];
}
//#endregion
export { useDiagramCompareLayout };
