import "../../_virtual/_rolldown/runtime.js";
import { createContext, useContext, useMemo } from "react";
import { shallowEqual } from "fast-equals";
import { nonNullable } from "@likec4/core";
import { useSelector } from "@xstate/react";
//#region src/overlays/relationships-browser/hooks.ts
var RelationshipsBrowserActorContext = createContext(null);
function useRelationshipsBrowserActor() {
	return nonNullable(useContext(RelationshipsBrowserActorContext), "No RelationshipsBrowserActorContext");
}
function useRelationshipsBrowserState(selector, compare = shallowEqual) {
	return useSelector(useRelationshipsBrowserActor(), selector, compare);
}
function useRelationshipsBrowser() {
	const actor = useRelationshipsBrowserActor();
	return useMemo(() => ({
		actor,
		get rootElementId() {
			return `relationships-browser-${actor.sessionId.replaceAll(":", "_")}`;
		},
		getState: () => actor.getSnapshot().context,
		send: actor.send,
		updateView: (layouted) => {
			if (actor.getSnapshot().status === "active") actor.send({
				type: "update.view",
				layouted
			});
		},
		changeScope: (scope) => {
			actor.send({
				type: "change.scope",
				scope
			});
		},
		navigateTo: (subject, fromNode) => {
			actor.send({
				type: "navigate.to",
				subject,
				fromNode
			});
		},
		fitDiagram: () => {
			actor.send({ type: "fitDiagram" });
		},
		close: () => {
			if (actor._parent) actor._parent?.send({
				type: "close",
				actorId: actor.id
			});
			else actor.send({ type: "close" });
		}
	}), [actor]);
}
//#endregion
export { RelationshipsBrowserActorContext, useRelationshipsBrowser, useRelationshipsBrowserState };
