import "../_virtual/_rolldown/runtime.js";
import { typedSystem } from "../likec4diagram/state/utils.js";
import { assertEvent, assign, enqueueActions, setup } from "xstate";
var searchActorLogic = setup({
	types: {
		context: {},
		events: {}
	},
	actions: {
		"reset navigateTo": assign({ navigateTo: () => null }),
		"assign navigateTo": assign(({ event }) => {
			assertEvent(event, ["navigate.to"]);
			return { navigateTo: {
				viewId: event.viewId,
				focusOnElement: event.focusOnElement
			} };
		}),
		"change searchValue": assign({ searchValue: ({ event, context }) => {
			assertEvent(event, ["change.search", "open"]);
			return event.search ?? context.searchValue;
		} }),
		"reset pickViewFor": assign({ pickViewFor: () => null })
	}
}).createMachine({
	id: "search",
	context: {
		openedWithSearch: null,
		searchValue: "",
		pickViewFor: null,
		navigateTo: null
	},
	initial: "inactive",
	on: { "close": { target: ".inactive" } },
	states: {
		inactive: {
			entry: ["reset navigateTo", "reset pickViewFor"],
			on: { "open": {
				target: "opened",
				actions: [assign({
					openedWithSearch: ({ event }) => event.search ?? null,
					searchValue: ({ event, context }) => event.search ?? context.searchValue
				})]
			} }
		},
		opened: { on: {
			"open": { actions: "change searchValue" },
			"change.search": { actions: "change searchValue" },
			"pickview.open": {
				target: "pickView",
				actions: assign({ pickViewFor: ({ event }) => event.elementFqn })
			},
			"navigate.to": {
				target: "waitAnimationEnd",
				actions: "assign navigateTo"
			}
		} },
		pickView: { on: {
			"pickview.close": {
				target: "opened",
				actions: "reset pickViewFor"
			},
			"navigate.to": {
				target: "waitAnimationEnd",
				actions: "assign navigateTo"
			}
		} },
		/**
		* Wait for animation end before triggering navigation
		* Otherwise, there could be weird artifacts when navigating to large diagrams.
		*/
		waitAnimationEnd: { on: { "animation.presence.end": {
			target: "inactive",
			actions: enqueueActions(({ context, system, enqueue }) => {
				const navigateTo = context.navigateTo;
				if (!navigateTo) return;
				enqueue("reset navigateTo");
				const diagramActor = typedSystem(system).diagramActorRef;
				if (navigateTo.focusOnElement) {
					if (diagramActor.getSnapshot().context.view.id === navigateTo.viewId) {
						enqueue.sendTo(diagramActor, {
							type: "focus.node",
							nodeId: navigateTo.focusOnElement
						});
						return;
					}
				}
				enqueue.sendTo(diagramActor, {
					type: "navigate.to",
					...navigateTo
				});
			})
		} } }
	}
});
//#endregion
export { searchActorLogic };
