import "../../_virtual/_rolldown/runtime.js";
import { machine, targetState, to } from "./machine.setup.js";
import { raiseFitDiagram } from "./machine.actions.layout.js";
import { assignFocusedNode, assignLastClickedNode, emitEdgeClick, emitNodeClick, emitOpenSourceOfView, emitPaneClick, openElementDetails, openSourceOfFocusedOrLastClickedNode, resetLastClickedNode } from "./machine.actions.js";
import { and, or } from "xstate/guards";
import { raise } from "xstate/actions";
//#region src/likec4diagram/state/machine.state.ready.idle.ts
var idle = machine.createStateConfig({
	id: targetState.idle.slice(1),
	on: {
		"xyflow.nodeClick": [
			{
				guard: and([
					"enabled: Readonly",
					"enabled: FocusMode",
					"click: node has connections",
					or(["click: same node", "click: selected node"])
				]),
				actions: [
					assignLastClickedNode(),
					assignFocusedNode(),
					emitNodeClick()
				],
				...to.focused
			},
			{
				guard: and([
					"enabled: Readonly",
					"enabled: ElementDetails",
					"click: node has modelFqn",
					or(["click: same node", "click: selected node"])
				]),
				actions: [
					assignLastClickedNode(),
					openSourceOfFocusedOrLastClickedNode(),
					openElementDetails(),
					emitNodeClick()
				]
			},
			{ actions: [
				assignLastClickedNode(),
				openSourceOfFocusedOrLastClickedNode(),
				emitNodeClick()
			] }
		],
		"xyflow.paneClick": { actions: [resetLastClickedNode(), emitPaneClick()] },
		"xyflow.paneDblClick": { actions: [
			resetLastClickedNode(),
			raiseFitDiagram(),
			emitOpenSourceOfView(),
			emitPaneClick()
		] },
		"focus.node": [{
			guard: "focus.node: autoUnfocus",
			actions: assignFocusedNode(),
			target: targetState.focused
		}, {
			guard: "enabled: FocusMode",
			actions: assignFocusedNode(),
			target: targetState.focused
		}],
		"xyflow.edgeClick": {
			guard: and([
				"enabled: Readonly",
				"is dynamic view",
				"enabled: DynamicViewWalkthrough",
				"click: selected edge"
			]),
			actions: [
				resetLastClickedNode(),
				raise(({ event }) => ({
					type: "walkthrough.start",
					stepId: event.edge.id
				})),
				emitEdgeClick()
			]
		}
	}
});
//#endregion
export { idle };
