import "../../../_virtual/_rolldown/runtime.js";
import { useCallbackRef } from "../../../hooks/useCallbackRef.js";
import { useUpdateEffect } from "../../../hooks/useUpdateEffect.js";
import { bezierControlPoints } from "../../../utils/xyflow.js";
import { useState } from "react";
import { deepEqual } from "fast-equals";
import { vector } from "@likec4/core/geometry";
//#region src/likec4diagram/custom/edges/useControlPoints.ts
function useControlPoints({ sourceX, sourceY, targetX, targetY, data }) {
	const [controlPoints, setControlPoints] = useState(() => data.controlPoints ?? bezierControlPoints(data.points));
	useUpdateEffect(() => {
		const next = data.controlPoints ?? bezierControlPoints(data.points);
		setControlPoints((prev) => deepEqual(prev, next) ? prev : next);
	}, [data.points, data.controlPoints ?? []]);
	return {
		controlPoints,
		setControlPoints,
		insertControlPoint: useCallbackRef(({ x, y }) => {
			const sourceV = vector(sourceX, sourceY);
			const targetV = vector(targetX, targetY);
			const points = [
				data.dir === "back" ? targetV : sourceV,
				...controlPoints.map(vector) || [],
				data.dir === "back" ? sourceV : targetV
			];
			const newPointV = vector(x, y).round();
			let insertionIndex = 0;
			let minDistance = Infinity;
			for (let i = 0; i < points.length - 1; i++) {
				const a = points[i];
				const b = points[i + 1];
				const fromCurrentToNext = b.subtract(a);
				const fromCurrentToNew = newPointV.subtract(a);
				const fromNextToNew = newPointV.subtract(b);
				if (fromCurrentToNext.dot(fromCurrentToNew) * fromCurrentToNext.dot(fromNextToNew) < 0) {
					const distanceToEdge = Math.abs(fromCurrentToNext.cross(fromCurrentToNew)) / fromCurrentToNext.length();
					if (distanceToEdge < minDistance) {
						minDistance = distanceToEdge;
						insertionIndex = i;
					}
				}
			}
			const newControlPoints = controlPoints.slice();
			newControlPoints.splice(insertionIndex, 0, {
				x: newPointV.x,
				y: newPointV.y
			});
			setControlPoints(newControlPoints);
			return newControlPoints;
		})
	};
}
//#endregion
export { useControlPoints };
