import "../_virtual/_rolldown/runtime.js";
import { isEmpty } from "remeda";
import { assertEvent, assign, emit, raise, setup } from "xstate";
var navigationPanelActorLogic = setup({
	types: {
		context: {},
		events: {},
		tags: "",
		input: {},
		emitted: {}
	},
	delays: {
		"open timeout": 500,
		"close timeout": 350
	},
	actions: {
		"update activatedBy": assign({ activatedBy: ({ context, event }) => {
			switch (true) {
				case event.type.includes("click"): return "click";
				case event.type.includes("mouseEnter"): return "hover";
				default: return context.activatedBy;
			}
		} }),
		"keep dropdown open": assign({ activatedBy: "click" }),
		"update selected folder": assign(({ event }) => {
			if (event.type === "breadcrumbs.click.root") return { selectedFolder: "" };
			assertEvent(event, ["breadcrumbs.click.folder", "select.folder"]);
			return { selectedFolder: event.folderPath };
		}),
		"reset selected folder": assign({ selectedFolder: ({ context }) => context.viewModel?.folder.path ?? "" }),
		"update inputs": assign(({ context, event }) => {
			assertEvent(event, "update.inputs");
			const viewChanged = event.inputs.viewModel?.id !== context.viewModel?.id;
			let selectedFolder = context.selectedFolder;
			if (!event.inputs.viewModel?.folder.path.startsWith(selectedFolder)) selectedFolder = event.inputs.viewModel?.folder.path ?? "";
			return {
				view: event.inputs.view,
				viewModel: event.inputs.viewModel,
				selectedFolder,
				activatedBy: viewChanged ? "hover" : context.activatedBy
			};
		}),
		"reset search query": assign({ searchQuery: "" }),
		"update search query": assign(({ event }) => {
			assertEvent(event, "searchQuery.change");
			return { searchQuery: event.value ?? "" };
		}),
		"emit navigateTo": emit(({ event }) => {
			assertEvent(event, "select.view");
			return {
				type: "navigateTo",
				viewId: event.viewId
			};
		})
	},
	guards: {
		"was opened on hover": ({ context }) => context.activatedBy === "hover",
		"has search query": ({ context }) => !isEmpty(context.searchQuery),
		"search query is empty": ({ context }) => isEmpty(context.searchQuery)
	}
}).createMachine({
	id: "breadcrumbs",
	context: ({ input }) => ({
		...input,
		breadcrumbs: [],
		activatedBy: "hover",
		selectedFolder: "",
		searchQuery: "",
		folderColumns: []
	}),
	initial: "idle",
	entry: ["update activatedBy", "reset selected folder"],
	on: {
		"update.inputs": { actions: "update inputs" },
		"searchQuery.change": { actions: ["update search query", raise({ type: "searchQuery.changed" })] }
	},
	states: {
		idle: {
			id: "idle",
			on: {
				"breadcrumbs.mouseEnter.*": {
					target: "pending",
					actions: "update activatedBy"
				},
				"breadcrumbs.click.*": {
					target: "active",
					actions: "update activatedBy"
				}
			}
		},
		pending: {
			on: {
				"breadcrumbs.mouseEnter.*": { actions: "update activatedBy" },
				"breadcrumbs.mouseLeave.*": { target: "idle" },
				"breadcrumbs.click.*": {
					target: "active",
					actions: "update activatedBy"
				}
			},
			after: { "open timeout": { target: "active" } }
		},
		active: {
			tags: ["active"],
			initial: "decide",
			on: {
				"dropdown.dismiss": { target: "#idle" },
				"breadcrumbs.mouseLeave": {
					guard: "was opened on hover",
					target: ".closing"
				},
				"dropdown.mouseLeave": {
					guard: "was opened on hover",
					target: ".closing"
				},
				"searchQuery.changed": { target: ".decide" }
			},
			states: {
				decide: { always: [{
					guard: "has search query",
					target: "search"
				}, { target: "opened" }] },
				opened: { on: {
					"searchQuery.changed": {
						guard: "has search query",
						actions: "keep dropdown open",
						target: "search"
					},
					"breadcrumbs.click.viewtitle": { actions: "reset selected folder" },
					"breadcrumbs.click.*": { actions: "update selected folder" },
					"select.folder": { actions: ["keep dropdown open", "update selected folder"] },
					"select.view": { actions: ["emit navigateTo"] }
				} },
				search: { on: {
					"breadcrumbs.click.viewtitle": {
						actions: ["reset search query", "reset selected folder"],
						target: "opened"
					},
					"breadcrumbs.click.*": {
						actions: ["reset search query", "update selected folder"],
						target: "opened"
					},
					"select.view": { actions: ["emit navigateTo"] }
				} },
				closing: {
					on: {
						"breadcrumbs.mouseEnter.*": { target: "decide" },
						"dropdown.mouseEnter": { target: "decide" }
					},
					after: { "close timeout": { target: "#idle" } }
				}
			}
		}
	}
});
//#endregion
export { navigationPanelActorLogic };
