import "../../../../_virtual/_rolldown/runtime.js";
import { useCallbackRef } from "../../../../hooks/useCallbackRef.js";
import { useDiagram } from "../../../../hooks/safeContext.js";
import { useState } from "react";
//#region src/likec4diagram/custom/nodes/toolbar/useHandlers.ts
function useHandlers(target, props) {
	const diagram = useDiagram();
	const [originalColor, setOriginalColor] = useState(null);
	const onColorPreview = useCallbackRef((color) => {
		if (color === null) {
			if (!originalColor) return;
			setOriginalColor(null);
			diagram.updateNodeData(props.data.id, { color: originalColor });
			return;
		}
		setOriginalColor((value) => value ?? props.data.color);
		diagram.updateNodeData(props.data.id, { color });
	});
	const onChange = useCallbackRef((change) => {
		const { shape, color, ...style } = change;
		diagram.updateNodeData(props.data.id, {
			...shape && { shape },
			...color && { color },
			style
		});
		diagram.triggerChange({
			op: "change-element-style",
			style: change,
			targets: [target]
		});
	});
	return {
		elementColor: originalColor ?? props.data.color,
		onColorPreview,
		onChange
	};
}
//#endregion
export { useHandlers };
