import "../../_virtual/_rolldown/runtime.js";
import { machine, targetState, to } from "./machine.setup.js";
import { assignViewportBefore, cancelFitDiagram, fitFocusedBounds, returnViewportBefore } from "./machine.actions.layout.js";
import { assignFocusedNode, assignLastClickedNode, cancelAutoUnfocusTimer, emitNodeClick, emitPaneClick, focusOnNodesAndEdges, openElementDetails, openSourceOfFocusedOrLastClickedNode, startAutoUnfocusTimer, startHotKeyActor, stopHotKeyActor, undimEverything } from "./machine.actions.js";
import { and } from "xstate/guards";
import { assign, raise } from "xstate/actions";
//#region src/likec4diagram/state/machine.state.ready.focused.ts
var focused = machine.createStateConfig({
	id: targetState.focused.slice(1),
	entry: [
		cancelFitDiagram(),
		focusOnNodesAndEdges(),
		assignViewportBefore(),
		openSourceOfFocusedOrLastClickedNode(),
		startHotKeyActor(),
		fitFocusedBounds(),
		startAutoUnfocusTimer()
	],
	exit: [
		stopHotKeyActor(),
		undimEverything(),
		returnViewportBefore(),
		cancelAutoUnfocusTimer(),
		assign({
			focusedNode: null,
			autoUnfocusTimer: false
		})
	],
	on: {
		"focus.autoUnfocus": { ...to.idle },
		"xyflow.nodeClick": [
			{
				guard: and([
					"enabled: ElementDetails",
					"click: focused node",
					"click: node has modelFqn"
				]),
				actions: [
					assignLastClickedNode(),
					openElementDetails(),
					emitNodeClick()
				]
			},
			{
				guard: "click: focused node",
				actions: [assignLastClickedNode(), emitNodeClick()],
				...to.idle
			},
			{ actions: [
				assignLastClickedNode(),
				raise(({ event }) => ({
					type: "focus.node",
					nodeId: event.node.id
				})),
				emitNodeClick()
			] }
		],
		"focus.node": { actions: [
			assignFocusedNode(),
			focusOnNodesAndEdges(),
			openSourceOfFocusedOrLastClickedNode(),
			fitFocusedBounds()
		] },
		"key.esc": { ...to.idle },
		"xyflow.paneClick": {
			actions: [emitPaneClick()],
			...to.idle
		},
		"notations.unhighlight": { actions: focusOnNodesAndEdges() },
		"tag.unhighlight": { actions: focusOnNodesAndEdges() }
	}
});
//#endregion
export { focused };
