import "../../_virtual/_rolldown/runtime.js";
import { DefaultFeatures } from "../../context/DiagramFeatures.js";
import { machine } from "./machine.setup.js";
import { updateEdgeData, updateNodeData } from "./assign.js";
import { cancelFitDiagram, raiseUpdateView } from "./machine.actions.layout.js";
import { assignDynamicViewVariant, emitOnLayoutTypeChange, stopEditorActor, triggerChange, updateFeatures, updateInputs } from "./machine.actions.js";
import { initializing, isReady } from "./machine.state.initializing.js";
import { navigating } from "./machine.state.navigating.js";
import { ready } from "./machine.state.ready.js";
import { DiagramToggledFeaturesPersistence } from "./persistence.js";
import { applyEdgeChanges, applyNodeChanges } from "@xyflow/react";
import { assign, stopChild } from "xstate/actions";
var diagramMachine = machine.createMachine({
	initial: "initializing",
	context: ({ input }) => ({
		...input,
		xyedges: [],
		xynodes: [],
		features: {
			...DefaultFeatures,
			...input.features
		},
		toggledFeatures: DiagramToggledFeaturesPersistence.read() ?? {
			enableReadOnly: true,
			enableCompareWithLatest: false
		},
		initialized: {
			xydata: false,
			xyflow: false
		},
		viewportChangedManually: false,
		lastOnNavigate: null,
		lastClickedNode: null,
		focusedNode: null,
		autoUnfocusTimer: false,
		activeElementDetails: null,
		viewportBefore: null,
		viewportOnManualLayout: null,
		viewportOnAutoLayout: null,
		navigationHistory: {
			currentIndex: 0,
			history: []
		},
		viewport: {
			x: 0,
			y: 0,
			zoom: 1
		},
		xyflow: null,
		dynamicViewVariant: input.dynamicViewVariant ?? (input.view._type === "dynamic" ? input.view.variant : "diagram") ?? "diagram",
		activeWalkthrough: null
	}),
	states: {
		initializing,
		isReady,
		ready,
		navigating,
		final: { type: "final" }
	},
	on: {
		"update.nodeData": { actions: assign(updateNodeData) },
		"update.edgeData": { actions: assign(updateEdgeData) },
		"switch.dynamicViewVariant": {
			guard: ({ context, event }) => context.dynamicViewVariant !== event.variant,
			actions: [
				assignDynamicViewVariant(),
				assign({ viewportChangedManually: false }),
				raiseUpdateView()
			]
		},
		"update.inputs": { actions: updateInputs() },
		"update.view-bounds": { actions: assign(({ context, event }) => {
			return { view: {
				...context.view,
				bounds: event.bounds
			} };
		}) },
		"update.features": { actions: updateFeatures() },
		"trigger.change": { actions: triggerChange() },
		"emit.onLayoutTypeChange": { actions: emitOnLayoutTypeChange() },
		"xyflow.applyChanges": { actions: assign(({ context, event }) => {
			return {
				xynodes: event.nodes ? applyNodeChanges(event.nodes, context.xynodes) : context.xynodes,
				xyedges: event.edges ? applyEdgeChanges(event.edges, context.xyedges) : context.xyedges
			};
		}) },
		"xyflow.viewportMoved": { actions: assign(({ event, context }) => ({
			viewportChangedManually: context.viewportChangedManually || event.manually,
			viewport: event.viewport
		})) },
		"destroy": {
			target: ".final",
			actions: [
				stopEditorActor(),
				cancelFitDiagram(),
				stopChild("hotkey"),
				stopChild("overlays"),
				stopChild("search"),
				stopChild("mediaPrint"),
				assign({
					xyflow: null,
					xystore: null,
					xyedges: [],
					xynodes: [],
					initialized: {
						xydata: false,
						xyflow: false
					}
				})
			]
		}
	}
});
//#endregion
export { diagramMachine };
