import "../../../_virtual/_rolldown/runtime.js";
import { useXYStore } from "../../../hooks/useXYFlow.js";
import { bezierPath, getNodeIntersectionFromCenterToPoint } from "../../../utils/xyflow.js";
import { useCallback } from "react";
import { shallowEqual } from "fast-equals";
import { first, isTruthy, last } from "remeda";
import { vector } from "@likec4/core/geometry";
import { nonNullable } from "@likec4/core/utils";
import { getNodeDimensions } from "@xyflow/system";
import { curveCatmullRomOpen, line } from "d3-shape";
//#region src/likec4diagram/custom/edges/useRelationshipEdgePath.ts
var curve = line().curve(curveCatmullRomOpen.alpha(.7)).x((d) => Math.trunc(d.x)).y((d) => Math.trunc(d.y));
/**
* @returns SVG path data string for relationship edge
*/
function useRelationshipEdgePath({ props: { sourceX, sourceY, source, target, targetX, targetY, data }, controlPoints, isControlPointDragging }) {
	const [sourceNodeWidth, sourceNodeHeight, targetNodeWidth, targetNodeHeight] = useXYStore(useCallback(({ nodeLookup }) => {
		const sourceNode = getNodeDimensions(nonNullable(nodeLookup.get(source), `source node ${source} not found`));
		const targetNode = getNodeDimensions(nonNullable(nodeLookup.get(target), `target node ${target} not found`));
		return [
			Math.ceil(sourceNode.width),
			Math.ceil(sourceNode.height),
			Math.ceil(targetNode.width),
			Math.ceil(targetNode.height)
		];
	}, [source, target]), shallowEqual);
	if (!(isTruthy(data.controlPoints) || isControlPointDragging)) return bezierPath(data.points);
	const sourceCenterPos = vector(sourceX, sourceY).trunc();
	const targetCenterPos = vector(targetX, targetY).trunc();
	const sourceNd = {
		...sourceCenterPos.subtract(vector(sourceNodeWidth, sourceNodeHeight).divide(2)).trunc().toObject(),
		width: sourceNodeWidth,
		height: sourceNodeHeight
	};
	const targetNd = {
		...targetCenterPos.subtract(vector(targetNodeWidth, targetNodeHeight).divide(2)).trunc().toObject(),
		width: targetNodeWidth,
		height: targetNodeHeight
	};
	const nodeMargin = 6;
	return nonNullable(curve(data.dir === "back" ? [
		targetCenterPos,
		getNodeIntersectionFromCenterToPoint(targetNd, first(controlPoints) ?? sourceCenterPos, nodeMargin),
		...controlPoints,
		getNodeIntersectionFromCenterToPoint(sourceNd, last(controlPoints) ?? targetCenterPos, nodeMargin),
		sourceCenterPos
	] : [
		sourceCenterPos,
		getNodeIntersectionFromCenterToPoint(sourceNd, first(controlPoints) ?? targetCenterPos, nodeMargin),
		...controlPoints,
		getNodeIntersectionFromCenterToPoint(targetNd, last(controlPoints) ?? sourceCenterPos, nodeMargin),
		targetCenterPos
	]));
}
//#endregion
export { useRelationshipEdgePath };
