import "../../_virtual/_rolldown/runtime.js";
import { machine } from "./machine.setup.js";
import { fitDiagram } from "./machine.actions.layout.js";
import { assignXYDataFromView, emitInitialized } from "./machine.actions.js";
import { assign } from "xstate/actions";
//#region src/likec4diagram/state/machine.state.initializing.ts
/**
* To be in `initializing` state, the diagram must wait for two events:
* - `xyflow.init` - indicates that the `xyflow` instance is ready
* - `update.view` - provides the initial diagram data (nodes and edges)
*
* Once both events have been received, the diagram transitions to `isReady` state.
*/
var initializing = machine.createStateConfig({ on: {
	"xyflow.init": {
		actions: assign(({ context, event }) => ({
			initialized: {
				...context.initialized,
				xyflow: true
			},
			xyflow: event.instance
		})),
		target: "isReady"
	},
	"update.view": {
		actions: [assignXYDataFromView(), assign(({ context }) => ({ initialized: {
			...context.initialized,
			xydata: true
		} }))],
		target: "isReady"
	}
} });
/**
* State that checks whether the diagram is ready to be used.
* Transitions to `ready` state if both `xyflow` and `xydata` are initialized,
* otherwise goes back to `initializing` state.`
*/
var isReady = machine.createStateConfig({ always: [{
	guard: "isReady",
	actions: [
		fitDiagram({ duration: 0 }),
		assign(({ context }) => ({ navigationHistory: {
			currentIndex: 0,
			history: [{
				viewId: context.view.id,
				viewport: { ...context.xyflow.getViewport() },
				viewportChangedManually: false
			}]
		} })),
		emitInitialized()
	],
	target: "ready"
}, { target: "initializing" }] });
//#endregion
export { initializing, isReady };
