import "../../_virtual/_rolldown/runtime.js";
import { assertEvent, assign, setup } from "xstate";
var RelationshipPopoverActorLogic = setup({
	types: {
		context: {},
		events: {},
		tags: "opened"
	},
	delays: {
		"open timeout": ({ context }) => context.openTimeout,
		"close timeout": 600,
		"long idle": 1500
	},
	actions: {
		"update edgeId": assign(({ context, event }) => {
			assertEvent(event, ["xyedge.select", "xyedge.mouseEnter"]);
			return {
				edgeId: event.edgeId,
				edgeSelected: context.edgeSelected || event.type === "xyedge.select"
			};
		}),
		"increase open timeout": assign(() => ({ openTimeout: 800 })),
		"decrease open timeout": assign(() => ({ openTimeout: 300 })),
		"reset edgeId": assign({
			edgeId: null,
			edgeSelected: false
		})
	},
	guards: {
		"edge was selected": ({ context }) => context.edgeSelected,
		"edge was hovered": ({ context }) => !context.edgeSelected
	}
}).createMachine({
	id: "breadcrumbs",
	context: () => ({
		edgeId: null,
		edgeSelected: false,
		openTimeout: 800
	}),
	initial: "idle",
	on: { "close": {
		target: "#idle",
		actions: ["reset edgeId", "increase open timeout"]
	} },
	states: {
		idle: {
			id: "idle",
			on: {
				"xyedge.mouseEnter": {
					target: "opening",
					actions: "update edgeId"
				},
				"xyedge.select": {
					target: "active",
					actions: "update edgeId"
				}
			},
			after: { "long idle": { actions: "increase open timeout" } }
		},
		opening: {
			on: {
				"xyedge.mouseLeave": { target: "idle" },
				"xyedge.select": {
					target: "active",
					actions: "update edgeId"
				}
			},
			after: { "open timeout": {
				actions: "decrease open timeout",
				target: "active"
			} }
		},
		active: {
			tags: ["opened"],
			initial: "opened",
			exit: "reset edgeId",
			on: {
				"xyedge.unselect": {
					target: "idle",
					actions: "increase open timeout"
				},
				"xyedge.select": { actions: "update edgeId" }
			},
			states: {
				opened: { on: {
					"dropdown.mouseEnter": { target: "hovered" },
					"xyedge.mouseLeave": {
						guard: "edge was hovered",
						target: "closing"
					}
				} },
				hovered: { on: { "dropdown.mouseLeave": [{
					guard: "edge was selected",
					target: "opened"
				}, { target: "closing" }] } },
				closing: {
					on: {
						"xyedge.mouseEnter": {
							guard: "edge was hovered",
							target: "opened",
							actions: "update edgeId"
						},
						"xyedge.select": {
							target: "opened",
							actions: "update edgeId"
						},
						"dropdown.mouseEnter": { target: "hovered" }
					},
					after: { "close timeout": { target: "#idle" } }
				}
			}
		}
	}
});
//#endregion
export { RelationshipPopoverActorLogic };
