import "../_virtual/_rolldown/runtime.js";
import { useOptionalCurrentViewModel } from "../context/LikeC4ModelContext.js";
//#region src/hooks/useCurrentViewModel.ts
/**
* Hook to get the current view model from the context.
* Throws an error if no view model is found in the context.
*
* @see useOptionalCurrentViewModel
*/
function useCurrentViewModel() {
	const vm = useOptionalCurrentViewModel();
	if (!vm) throw new Error("No CurrentViewModelContext found");
	return vm;
}
//#endregion
export { useCurrentViewModel };
