import "../../_virtual/_rolldown/runtime.js";
import { fromCallback } from "xstate";
//#region src/likec4diagram/state/mediaPrintActor.ts
/**
* Actor logic to listen for media print events.
*/
var mediaPrintActorLogic = fromCallback(({ sendBack }) => {
	const beforePrint = () => {
		sendBack({ type: "media.print.on" });
	};
	const afterPrint = () => {
		sendBack({ type: "media.print.off" });
	};
	window.addEventListener("beforeprint", beforePrint);
	window.addEventListener("afterprint", afterPrint);
	return () => {
		window.removeEventListener("beforeprint", beforePrint);
		window.removeEventListener("afterprint", afterPrint);
	};
});
//#endregion
export { mediaPrintActorLogic };
