import "../../_virtual/_rolldown/runtime.js";
import { relationshipsBrowserLogic } from "../relationships-browser/actor.js";
import { assign, sendTo, setup, spawnChild, stopChild } from "xstate";
var elementDetailsLogic = setup({
	types: {
		context: {},
		input: {},
		events: {},
		children: {}
	},
	actors: { relationshipsBrowserLogic }
}).createMachine({
	id: "element-details",
	context: ({ input }) => ({
		...input,
		initiatedFrom: {
			node: input.initiatedFrom?.node ?? null,
			clientRect: input.initiatedFrom?.clientRect ?? null
		}
	}),
	initial: "active",
	states: {
		"active": {
			entry: spawnChild("relationshipsBrowserLogic", {
				id: ({ self }) => `${self.id}-relationships`,
				input: ({ context }) => ({
					subject: context.subject,
					viewId: context.currentView.id,
					scope: "view",
					enableSelectSubject: false,
					enableChangeScope: true,
					closeable: false
				})
			}),
			exit: [sendTo(({ self }) => `${self.id}-relationships`, { type: "close" }), stopChild(({ self }) => `${self.id}-relationships`)],
			on: {
				"change.subject": { actions: assign({ subject: ({ event }) => event.subject }) },
				"close": "closed"
			}
		},
		closed: {
			id: "closed",
			type: "final"
		}
	}
});
//#endregion
export { elementDetailsLogic };
