import "../_virtual/_rolldown/runtime.js";
import { relationshipsBrowserLogic } from "./relationships-browser/actor.js";
import { elementDetailsLogic } from "./element-details/actor.js";
import { relationshipDetailsLogic } from "./relationship-details/actor.js";
import { isString, last, reverse } from "remeda";
import { getHotkeyHandler } from "@mantine/hooks";
import { assertEvent, fromCallback, setup } from "xstate";
import { not } from "xstate/guards";
//#region src/overlays/overlaysActor.ts
var machine = setup({
	types: {
		context: {},
		events: {},
		emitted: {},
		children: {}
	},
	actors: {
		relationshipDetails: relationshipDetailsLogic,
		elementDetails: elementDetailsLogic,
		relationshipsBrowser: relationshipsBrowserLogic,
		hotkey: fromCallback(({ sendBack }) => {
			const handler = getHotkeyHandler([[
				"Escape",
				(event) => {
					event.stopPropagation();
					sendBack({ type: "close" });
				},
				{ preventDefault: true }
			]]);
			document.body.addEventListener("keydown", handler, { capture: true });
			return () => {
				document.body.removeEventListener("keydown", handler, { capture: true });
			};
		})
	},
	guards: {
		"has overlays?": ({ context }) => context.overlays.length > 0,
		"close specific overlay?": ({ context, event }) => {
			assertEvent(event, "close");
			return isString(event.actorId) && context.overlays.some((o) => o.id === event.actorId);
		},
		"last: is relationshipDetails?": ({ context }) => {
			return last(context.overlays)?.type === "relationshipDetails";
		},
		"last: is relationshipsBrowser?": ({ context }) => {
			return last(context.overlays)?.type === "relationshipsBrowser";
		}
	}
});
var emitOpened = (overlay) => machine.emit({
	type: "opened",
	overlay: overlay.split("-")[0]
});
var emitClosed = (overlay) => machine.emit({
	type: "closed",
	overlay: overlay.split("-")[0]
});
var emitIdle = () => machine.emit({ type: "idle" });
var closeLastOverlay = () => machine.enqueueActions(({ context, enqueue }) => {
	if (context.overlays.length === 0) return;
	const lastOverlay = last(context.overlays)?.id;
	if (!lastOverlay) return;
	enqueue.sendTo(lastOverlay, { type: "close" });
	enqueue.stopChild(lastOverlay);
	enqueue.assign({ overlays: context.overlays.filter((o) => o.id !== lastOverlay) });
	enqueue(emitClosed(lastOverlay));
});
var closeSpecificOverlay = () => machine.enqueueActions(({ context, enqueue, event }) => {
	assertEvent(event, "close");
	const actorId = event.actorId;
	if (!isString(actorId)) return;
	const toClose = context.overlays.find((o) => o.id === actorId)?.id;
	if (toClose) {
		enqueue.sendTo(toClose, { type: "close" });
		enqueue.stopChild(toClose);
		enqueue.assign({ overlays: context.overlays.filter((o) => o.id !== toClose) });
		enqueue(emitClosed(toClose));
	}
});
var closeAllOverlays = () => machine.enqueueActions(({ context, enqueue }) => {
	for (const { id } of reverse(context.overlays)) {
		enqueue.sendTo(id, { type: "close" });
		enqueue.stopChild(id);
		enqueue(emitClosed(id));
	}
	enqueue.assign({ overlays: [] });
});
var openElementDetails = () => machine.enqueueActions(({ context, enqueue, event }) => {
	assertEvent(event, "open.elementDetails");
	if (context.overlays.some((o) => o.type === "elementDetails" && o.subject === event.subject)) return;
	const id = `elementDetails-${context.seq}`;
	enqueue.spawnChild("elementDetails", {
		id,
		input: event,
		syncSnapshot: true
	});
	enqueue.assign({
		seq: context.seq + 1,
		overlays: [...context.overlays, {
			id,
			type: "elementDetails",
			subject: event.subject
		}]
	});
	enqueue(emitOpened(id));
});
var openRelationshipDetails = () => machine.enqueueActions(({ context, enqueue, event }) => {
	assertEvent(event, "open.relationshipDetails");
	const currentOverlay = last(context.overlays);
	if (currentOverlay?.type === "relationshipDetails") {
		enqueue.sendTo(currentOverlay.id, {
			...event,
			type: "navigate.to"
		});
		return;
	}
	const id = `relationshipDetails-${context.seq}`;
	enqueue.spawnChild("relationshipDetails", {
		id,
		input: event,
		syncSnapshot: true
	});
	enqueue.assign({
		seq: context.seq + 1,
		overlays: [...context.overlays, {
			id,
			type: "relationshipDetails"
		}]
	});
	enqueue(emitOpened(id));
});
var openRelationshipsBrowser = () => machine.enqueueActions(({ context, enqueue, event }) => {
	assertEvent(event, "open.relationshipsBrowser");
	const currentOverlay = last(context.overlays);
	if (currentOverlay?.type === "relationshipsBrowser") {
		enqueue.sendTo(currentOverlay.id, {
			type: "navigate.to",
			subject: event.subject,
			viewId: event.viewId
		});
		return;
	}
	const id = `relationshipsBrowser-${context.seq}`;
	enqueue.spawnChild("relationshipsBrowser", {
		id,
		input: event,
		syncSnapshot: true
	});
	enqueue.assign({
		seq: context.seq + 1,
		overlays: [...context.overlays, {
			id,
			type: "relationshipsBrowser",
			subject: event.subject
		}]
	});
	enqueue(emitOpened(id));
});
var openOverlay = () => machine.enqueueActions(({ enqueue, event }) => {
	assertEvent(event, [
		"open.elementDetails",
		"open.relationshipDetails",
		"open.relationshipsBrowser"
	]);
	switch (event.type) {
		case "open.elementDetails":
			enqueue(openElementDetails());
			break;
		case "open.relationshipDetails":
			enqueue(openRelationshipDetails());
			break;
		case "open.relationshipsBrowser":
			enqueue(openRelationshipsBrowser());
			break;
	}
});
var listenToEsc = () => machine.spawnChild("hotkey", { id: "hotkey" });
var stopListeningToEsc = () => machine.stopChild("hotkey");
var checkState = () => machine.enqueueActions(({ enqueue, context }) => {
	if (context.overlays.length === 0) enqueue.raise({ type: "close" });
});
var overlaysActorLogic = machine.createMachine({
	id: "overlays",
	context: () => ({
		seq: 1,
		overlays: []
	}),
	initial: "idle",
	states: {
		idle: {
			entry: [emitIdle()],
			on: { "open.*": {
				actions: openOverlay(),
				target: "active"
			} }
		},
		active: {
			entry: [listenToEsc()],
			exit: [stopListeningToEsc()],
			on: {
				"open.*": { actions: openOverlay() },
				"close": [
					{
						guard: not("has overlays?"),
						target: "idle"
					},
					{
						guard: "close specific overlay?",
						actions: [closeSpecificOverlay(), checkState()]
					},
					{ actions: [closeLastOverlay(), checkState()] }
				],
				"close.all": {
					actions: [closeAllOverlays()],
					target: "idle"
				}
			}
		},
		final: {
			entry: [closeAllOverlays(), stopListeningToEsc()],
			type: "final"
		}
	}
});
//#endregion
export { overlaysActorLogic };
