import "../../_virtual/_rolldown/runtime.js";
import { isBoolean, pickBy } from "remeda";
//#region src/likec4diagram/state/persistence.ts
var key = `likec4:diagram:toggledFeatures`;
var DiagramToggledFeaturesPersistence = {
	read() {
		try {
			let fromStorage = sessionStorage.getItem(key);
			if (fromStorage) return JSON.parse(fromStorage);
			return null;
		} catch (e) {
			console.error(`Error reading fromStorage ${key}:`, e);
			return null;
		}
	},
	write(toggledFeatures) {
		sessionStorage.setItem(key, JSON.stringify(pickBy(toggledFeatures, isBoolean)));
		return toggledFeatures;
	}
};
//#endregion
export { DiagramToggledFeaturesPersistence };
