/**
* Center-Bottom action bar, includes zoom-in and browse relationships actions, if the features are enabled.
* Intended to be used with model elements.
*
* Use generic {@link ElementActionButtons} for custom action buttons.
*
* @param extraButtons - Add extra action buttons
*
* @example
* ```tsx
* <ElementActions
*   extraButtons={[
*     {
*       key: 'extra',
*       icon: <IconZoomScan />,
*       onClick: (e) => {
*         e.stopPropagation()
*         console.log('extra action clicked')
*       },
*       },
*     },
*   ]}
* />
* ```
*/
function ElementActions({ extraButtons, ...props }) {
	const { enableNavigateTo, enableRelationshipBrowser } = useEnabledFeatures();
	const diagram = useDiagram();
	const { id, navigateTo, modelFqn } = props.data;
	let buttons = useMemo(() => {
		const buttons = [];
		if (navigateTo && enableNavigateTo) buttons.push({
			key: "navigate",
			icon: /* @__PURE__ */ jsx(IconZoomScan, {}),
			onClick: (e) => {
				e.stopPropagation();
				diagram.navigateTo(navigateTo, id);
			}
		});
		if (enableRelationshipBrowser) buttons.push({
			key: "relationships",
			icon: /* @__PURE__ */ jsx(IconTransform, {}),
			onClick: (e) => {
				e.stopPropagation();
				diagram.openRelationshipsBrowser(modelFqn);
			}
		});
		return buttons;
	}, [
		enableNavigateTo,
		enableRelationshipBrowser,
		modelFqn,
		navigateTo,
		id,
		diagram
	]);
	if (extraButtons && hasAtLeast(extraButtons, 1)) buttons = [...buttons, ...extraButtons];
	return /* @__PURE__ */ jsx(ElementActionButtons, {
		...props,
		buttons
	});
}
