import "../_virtual/_rolldown/runtime.js";
import { machine } from "./editorActor.setup.js";
import { addSnapshotToPendingChanges, cancelSync, ensureHotKey, isLayoutChange, markHistoryAsSynched, pushHistory, reschedule, saveStateBeforeEdit, startEditing, stopEditing, stopHotkey, undo, withoutSnapshotChanges } from "./editorActor.actions.js";
import { find } from "remeda";
import { assign, enqueueActions, log, sendTo } from "xstate";
//#region src/editor/editorActor.states.ts
/**
* Actually this is DiagramActorRef
* But we can't use it here due to circular type inference
*/
var diagramActorRef = function(params) {
	return params.system.get("diagram");
};
var to = {
	idle: { target: "#idle" },
	editing: { target: "#editing" },
	afterEdit: { target: "#afterEdit" },
	pending: { target: "#pending" },
	applyLatestToManual: { target: "#applyLatestToManual" },
	executeChanges: { target: "#executeChanges" }
};
/**
* Idle state, no pending operations
*/
var idle = machine.createStateConfig({
	id: "idle",
	on: {
		"sync": { ...to.pending },
		"edit.start": { ...to.editing }
	}
});
/**
* Edit state, some operation is in progress, come to this state from idle
*/
var editing = machine.createStateConfig({
	id: "editing",
	tags: "pending",
	entry: [startEditing(), cancelSync()],
	on: {
		change: {
			actions: stopEditing(),
			...to.executeChanges
		},
		"edit.finish": {
			actions: stopEditing(),
			...to.afterEdit
		},
		"undo": {
			actions: stopEditing(),
			...to.idle
		}
	}
});
/**
* Syncing state, some edits are not yet synced
*/
var pending = machine.createStateConfig({
	id: "pending",
	tags: ["pending"],
	entry: ensureHotKey(),
	on: {
		"sync": {
			reenter: true,
			...to.pending
		},
		"edit.start": {
			actions: [addSnapshotToPendingChanges()],
			...to.editing
		}
	},
	after: { "waitBeforeSync": {
		actions: [addSnapshotToPendingChanges()],
		...to.executeChanges
	} }
});
/**
* Decide where to go next
*/
var afterEdit = machine.createStateConfig({
	id: "afterEdit",
	always: [{
		guard: "has pending",
		...to.pending
	}, { ...to.idle }]
});
/**
* Syncing state, some edits are not yet synced
*/
var applyLatestToManual = machine.createStateConfig({
	id: "applyLatestToManual",
	entry: [cancelSync(), saveStateBeforeEdit()],
	initial: "call",
	states: {
		call: { invoke: {
			src: "applyLatest",
			input: ({ context }) => {
				const current = context.beforeEditing?.change.layout;
				return {
					current: current && current._layout === "manual" ? current : void 0,
					viewId: context.viewId
				};
			},
			onDone: {
				actions: sendTo(diagramActorRef, ({ event }) => ({
					type: "update.view",
					view: event.output.updated
				}), { delay: 10 }),
				target: "wait"
			},
			onError: {
				actions: [assign({
					beforeEditing: null,
					pendingChanges: []
				}), ({ event }) => {
					console.error(event.error);
				}],
				...to.idle
			}
		} },
		wait: {
			entry: pushHistory(),
			on: { "*": { actions: [log(({ event }) => `wait received unexpected event: ${event.type}`), reschedule(500)] } },
			after: { "500ms": {
				actions: [addSnapshotToPendingChanges(), ensureHotKey()],
				...to.executeChanges
			} }
		}
	}
});
/**
* Calls `executeChange` to save the snapshot
*/
var executeChanges = machine.createStateConfig({
	id: "executeChanges",
	entry: [assign(({ event, context }) => {
		if (event.type === "change") {
			if (isLayoutChange(event.change)) return { pendingChanges: [...withoutSnapshotChanges(context.pendingChanges), event.change] };
			if (!context.pendingChanges.includes(event.change)) return { pendingChanges: [...context.pendingChanges, event.change] };
		}
		return {};
	}), cancelSync()],
	invoke: {
		src: "executeChange",
		input: ({ context }) => ({
			changes: context.pendingChanges,
			viewId: context.viewId
		}),
		onDone: {
			actions: enqueueActions(({ context, event, enqueue }) => {
				const snapshot = find(context.pendingChanges, (c) => c.op === "save-view-snapshot");
				if (snapshot) enqueue.sendTo(diagramActorRef, {
					type: "update.view-bounds",
					bounds: snapshot.layout.bounds
				});
				enqueue.assign({ pendingChanges: [] });
			}),
			...to.idle
		},
		onError: {
			actions: assign(({ event }) => {
				console.error("executeChanges onError", { error: event.error });
				return { pendingChanges: [] };
			}),
			...to.idle
		}
	}
});
var editorActorLogic = machine.createMachine({
	id: "editor",
	context: ({ input }) => ({
		viewId: input.viewId,
		beforeEditing: null,
		editing: null,
		pendingChanges: [],
		history: []
	}),
	initial: "idle",
	states: {
		idle,
		editing,
		pending,
		afterEdit,
		applyLatestToManual,
		executeChanges
	},
	on: {
		cancel: {
			actions: [cancelSync(), assign({
				editing: null,
				beforeEditing: null,
				pendingChanges: []
			})],
			...to.idle
		},
		synced: { actions: markHistoryAsSynched() },
		undo: {
			guard: "can undo",
			actions: undo(),
			...to.idle
		},
		change: { ...to.executeChanges },
		"applyLatestToManual": { ...to.applyLatestToManual },
		reset: {
			actions: [
				cancelSync(),
				assign({
					history: [],
					editing: null,
					beforeEditing: null,
					pendingChanges: []
				}),
				stopHotkey()
			],
			...to.idle
		}
	}
});
//#endregion
export { editorActorLogic };
